/**
 * Every UTC instant (0, 1 or 2) at which the zone's wall clock reads
 * `year-month-day hour:00`. Two when the hour repeats at a DST fall-back;
 * none when it is skipped by a spring-forward (then the transition instant is
 * returned, the moment the clock jumped past it).
 */
function wallClockInstants(
  year: number,
  month: number,
  day: number,
  hour: number,
  timeZone: string,
): number[] {
  const guess = Date.UTC(year, month - 1, day, hour, 0, 0, 0);
  const offsets = new Set([
    offsetAt(guess - DAY_MS, timeZone),
    offsetAt(guess, timeZone),
    offsetAt(guess + DAY_MS, timeZone),
  ]);
  const found = new Set<number>();
  for (const offset of offsets) {
    const candidate = guess - offset;
    if (offsetAt(candidate, timeZone) === offset) found.add(candidate);
  }
  if (found.size === 0) {
    return [guess - offsetAt(guess - DAY_MS, timeZone)];
  }
  return [...found].sort((a, b) => a - b);
