}

function parseDateString(date: string): [number, number, number] {
  const match = /^(\\d{4})-(\\d{2})-(\\d{2})$/.exec(date);
  if (!match) throw new RangeError(`Malformed local date: "${date}"`);
  return [Number(match[1]), Number(match[2]), Number(match[3])];
}

/** `date` (YYYY-MM-DD) shifted by whole calendar days. */
export function shiftLocalDate(date: string, days: number): string {
  const [y, m, d] = parseDateString(date);
  const shifted = new Date(Date.UTC(y, m - 1, d + days));
  return `${pad(shifted.getUTCFullYear(), 4)}-${pad(shifted.getUTCMonth() + 1)}-${pad(shifted.getUTCDate())}`;
}

/** The UTC instant at which the zone's calendar day `date` began. */
export function localMidnight(date: string, timeZone: string): IsoTimestamp {
  const [y, m, d] = parseDateString(date);
  return toIsoTimestamp(new Date(wallClockInstants(y, m, d, 0, timeZone)[0]!));
}

/** The UTC instant at which the zone's calendar day containing `reference` began. */
export function startOfLocalDay(
  reference: Date,
  timeZone: string,
): IsoTimestamp {
  const { year, month, day } = localParts(reference.getTime(), timeZone);
  return localMidnight(`${pad(year, 4)}-${pad(month)}-${pad(day)}`, timeZone);
}

/**
 * True once the calendar day (on the zone's clock) containing `dueAt` has
 * ended. Due dates are whole days: on the day itself nothing is overdue.
 */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  if (dueAt === null) return false;
  return (
    parseIso(dueAt).getTime() <
    parseIso(startOfLocalDay(reference, timeZone)).getTime()
  );
}

